import React, { useState, useEffect } from "react";
import "./ViewTasks.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";
import axios from "axios";

const ViewTasks = () => {
  const [milestones, setMilestones] = useState([]);
  const [newMilestone, setNewMilestone] = useState("");
  const [newTask, setNewTask] = useState({ title: "", creator: "", status: "Pending" });
  const [student, setStudent] = useState(null);
  const [group, setGroup] = useState(null);
  const [loading, setLoading] = useState(true);

  const user = JSON.parse(localStorage.getItem("users"));

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Get student data
        const studentRes = await axios.get(`http://localhost:5000/api/student/${user.id}`);
        const studentData = studentRes.data;
        setStudent(studentData);

        if (!studentData.isGrouped) {
          alert("You are not assigned to a group yet.");
          setLoading(false);
          return;
        }

        // Get all groups to find current student's group
        const groupRes = await axios.get("http://localhost:5000/api/group");
        const studentGroup = groupRes.data.find(g => g.studentsRegno.includes(studentData.regNo));
        if (!studentGroup) {
          alert("Group not found.");
          setLoading(false);
          return;
        }

        setGroup(studentGroup);

        // Fetch all milestones
        const milestoneRes = await axios.get("http://localhost:5000/api/milestone");
        const projectMilestones = milestoneRes.data.filter(m => m.projectID === studentGroup.projectID);

        // Fetch all tasks
        const taskRes = await axios.get("http://localhost:5000/api/task");

        // Combine milestones and tasks
        const combined = projectMilestones.map(m => ({
          id: m._id,
          name: m.title,
          createdAt: new Date(m.createdAt).toLocaleString(),
          tasks: taskRes.data
            .filter(t => t.milestoneId === m._id)
            .map(t => ({
              id: t._id,
              title: t.title,
              creator: t.uploadedBy,
              status: t.status,
              completedBy: t.completedBy || "",
              createdAt: new Date(t.createdAt).toLocaleString()
            }))
        }));

        setMilestones(combined);
        setLoading(false);
      } catch (err) {
        console.error("Error fetching data:", err);
        setLoading(false);
      }
    };

    fetchData();
  }, [user.id]); // ✅ Warning fixed

  const handleAddMilestone = async () => {
    if (!newMilestone.trim()) {
      alert("Please enter a milestone name.");
      return;
    }

    try {
      const res = await axios.post("http://localhost:5000/api/milestone", {
        projectID: group.projectID,
        title: newMilestone,
        dueDate: new Date(),
        status: "Pending"
      });

      const ms = res.data;

      setMilestones([...milestones, {
        id: ms._id,
        name: ms.title,
        createdAt: new Date(ms.createdAt).toLocaleString(),
        tasks: []
      }]);

      setNewMilestone("");
    } catch (err) {
      console.error("Error adding milestone:", err);
    }
  };

  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim() || !newTask.creator.trim()) {
      alert("Please fill in all task fields.");
      return;
    }

    try {
      const res = await axios.post("http://localhost:5000/api/task", {
        milestoneId: milestoneId,
        title: newTask.title,
        status: newTask.status,
        uploadedBy: newTask.creator
      });

      const task = res.data;

      setMilestones(milestones.map(m => {
        if (m.id === milestoneId) {
          return {
            ...m,
            tasks: [...m.tasks, {
              id: task._id,
              title: task.title,
              creator: task.uploadedBy,
              status: task.status,
              completedBy: "",
              createdAt: new Date(task.createdAt).toLocaleString()
            }]
          };
        }
        return m;
      }));

      setNewTask({ title: "", creator: "", status: "Pending" });
    } catch (err) {
      console.error("Error adding task:", err);
    }
  };

  const handleUpdateTaskStatus = (milestoneId, taskId, newStatus) => {
    setMilestones(milestones.map(m => {
      if (m.id === milestoneId) {
        return {
          ...m,
          tasks: m.tasks.map(task =>
            task.id === taskId
              ? { ...task, status: newStatus, completedBy: student.studentName }
              : task
          )
        };
      }
      return m;
    }));
  };

  if (loading) return <div>Loading...</div>;
  if (!student || !student.isGrouped) return <div>You are not allowed to view tasks.</div>;

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>

          <div className="milestone-section">
            <input
              type="text"
              value={newMilestone}
              onChange={(e) => setNewMilestone(e.target.value)}
              placeholder="Add a new milestone"
            />
            <button onClick={handleAddMilestone}>Add Milestone</button>
          </div>

          <div className="milestone-list">
            {milestones.map((milestone) => (
              <div key={milestone.id} className="milestone-item">
                <h2>{milestone.name}</h2>
                <p>Created on: {milestone.createdAt}</p>

                <div className="task-section">
                  <input
                    type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                    placeholder="Task title"
                  />
                  <input
                    type="text"
                    value={newTask.creator}
                    onChange={(e) => setNewTask({ ...newTask, creator: e.target.value })}
                    placeholder="Created by"
                  />
                  <button className="task-button" onClick={() => handleAddTask(milestone.id)}>Add Task</button>

                  <div className="tasks-table">
                    <table>
                      <thead>
                        <tr>
                          <th>Task</th>
                          <th>Creator</th>
                          <th>Status</th>
                          <th>Completed By</th>
                          <th>Created At</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {milestone.tasks.map((task) => (
                          <tr key={task.id}>
                            <td>{task.title}</td>
                            <td>{task.creator}</td>
                            <td>{task.status}</td>
                            <td>{task.completedBy || "N/A"}</td>
                            <td>{task.createdAt}</td>
                            <td>
                              {task.status !== "Completed" && (
                                <button
                                  className="mark-completed-button"
                                  onClick={() => handleUpdateTaskStatus(milestone.id, task.id, "Completed")}
                                >
                                  Mark as Completed
                                </button>
                              )}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
